#!/usr/bin/env python3
"""The first nonlinear return into a parent generated by actual pure swirl.

Exact initial NS jets retain viscosity, canonical reconstruction and both
source deformation and parent transport. A radial identity gives negative
return for a whole seed class; the same calculation exhibits its generated
angular defect. Actual time-interval comparisons are analytic, not Lean
certificates, and no repeated-renewal or arbitrary-data bound is asserted.
"""

import json
import sympy as s
from rotational_curl_reserve import require, zero
from rotational_joint_enstrophy import r, z, grad, lap5, velocity
from critical_parent_transport import moment


x = s.symbols('x', positive=True)


def sphere_mean(expr):
    """Normalized S4 angular mean at fixed squared radius x."""
    result = 0
    for (m,), coefficient in s.Poly(s.expand(expr), z).terms():
        require(m % 2 == 0, 'even axial angular polynomial')
        k = m // 2
        result += coefficient*x**k*s.rf(s.Rational(1, 2), k)/s.rf(s.Rational(5, 2), k)
    return s.factor(result)


def rational_integral(expr):
    """Exact R5 beta moments for this finite rational-power test class."""
    base = s.symbols('base', positive=True)
    expression = s.expand(s.cancel(expr.subs(r*r, base-1-z*z)))
    result = 0
    for term in s.Add.make_args(expression):
        powers = term.as_powers_dict()
        m, k = powers.get(z, 0), -powers.get(base, 0)
        coefficient = s.cancel(term/(z**m*base**(-k)))
        require(not coefficient.has(r, z, base), 'every spatial power is retained')
        require(m.is_integer if hasattr(m, 'is_integer') else isinstance(m, int),
                'integer axial power')
        if m % 2 == 0:
            result += coefficient*moment(m, k)
    return s.factor(s.expand_func(result))


def actual_jets():
    b, chi = [s.Function(n)(r, z) for n in ('b0', 'chi1')]
    nu = s.symbols('nu', positive=True)
    f = b*b
    v, q = velocity(chi), 2*s.diff(chi, z)
    h1 = s.diff(f, z)
    b1 = nu*lap5(b)
    b2cal = nu**2*lap5(lap5(b))
    b2 = b2cal-v.dot(grad(b))+q*b
    h2 = nu*lap5(h1)+2*s.diff(b*b1, z)
    h3cal = nu*lap5(h2)+2*s.diff(b1*b1+b*b2cal, z)
    h3 = nu*lap5(h2)-2*v.dot(grad(h1))+2*s.diff(b1*b1+b*b2, z)
    f2nonlinear = -v.dot(grad(f))+2*q*f
    h3nonlinear = s.diff(f2nonlinear, z)-2*v.dot(grad(h1))
    zero(h3-h3cal-h3nonlinear,
         'complete third parent jet splits into caloric and nonlinear parts')
    zero(h2-nu*(lap5(h1)+2*s.diff(b*lap5(b), z)),
         'the second parent jet is exactly the caloric viscous jet')
    zero(h3cal-nu**2*(lap5(lap5(h1))+2*lap5(s.diff(b*lap5(b), z))
         +2*s.diff(lap5(b)**2+b*lap5(lap5(b)), z)),
         'all viscosity-squared terms in the third parent jet are retained')
    div5 = lambda u: s.diff(u[0], r)+3*u[0]/r+s.diff(u[1], z)
    zero(div5(v)+q, 'lifted transport divergence is minus q')
    zero(div5(chi*v), 'parent self-transport has zero canonical pairing')
    zero(chi*s.diff(f2nonlinear, z)+q*f2nonlinear/2
         -s.diff(chi*f2nonlinear, z), 'source pairing keeps its boundary derivative')
    zero(q*v.dot(grad(f))+f*v.dot(grad(q))-q*q*f-div5(q*f*v),
         'full source deformation reduces to the signed return integrand')
    p = s.Rational(5, 2)
    zero(p*b**(p-1)*(-v.dot(grad(b))+q*b)+div5(v*b**p)-(p-1)*q*b**p,
         'critical observer comparison retains the full source transport')
    t, a1, a2, a3, j3 = s.symbols('t a1 a2 a3 j3', real=True)
    cal = t*a1+t*t*a2/2+t**3*a3/6
    actual = cal+t**3*j3/6
    zero(s.expand(actual**2-cal**2).coeff(t, 4)-a1*j3/3,
         'the first parent-energy comparison is one third of the return pairing')
    return {'source': 'f=b0^2; h1=partial_z f; chi1=(-Delta5)^-1 h1; v1=velocity(chi1); q1=2partial_z chi1',
            'second_source': 'f2_nonlin=-v1.grad f+2q1 f',
            'third_parent': 'h3_nonlin=partial_z f2_nonlin-2v1.grad h1',
            'return': 'C_return=<chi1,h3_nonlin>=-1/2 integral f[v1.grad q1+q1^2]',
            'physical_comparison': '||a(t)||2^2-||a_cal(t)||2^2=(t^4/3)C_return+o(t^4)',
            'viscosity': 'same full caloric jets through order two; every nu^2 third-jet term cancels in the difference',
            'scope': 'continuous local-history and Hilbert-space Taylor passage analytic; no uniform time window'}


def radial_identity():
    g = s.Function('g')(x)
    gp, gpp = s.diff(g, x), s.diff(g, x, 2)
    f = 4*x*gp+10*g
    vr = 2*r*g+4*r*z*z*gp
    vz = -4*z*g-4*r*r*z*gp
    q = -4*g-8*z*z*gp
    adv = lambda expr: s.expand((vr*(2*r*s.diff(expr, x))
                                +vz*(s.diff(expr, z)+2*z*s.diff(expr, x)))
                               .subs(r*r, x-z*z))
    A = 42*x*g*gp+4*x*x*g*gpp+28*x*x*gp**2+35*g**2
    zero(sphere_mean(adv(q)+q*q)-s.Rational(16, 35)*A,
         'complete angular average includes every transport contribution')
    boundary = (8*x**s.Rational(9, 2)*g*gp**2
                +40*x**s.Rational(7, 2)*g*g*gp
                +140*x**s.Rational(5, 2)*g**3)
    positive = 4*x**s.Rational(7, 2)*gp**2*(26*x*gp+83*g)
    zero(x**s.Rational(3, 2)*f*A-positive-s.diff(boundary, x),
         'exact radial integration-by-parts identity with explicit endpoint term')
    zero(26*x*gp+83*g-s.Rational(13, 2)*f-18*g,
         'radial nonnegative source gives nonnegative return density')
    zero(s.diff(x**s.Rational(5, 2)*g, x)-x**s.Rational(3, 2)*f/4,
         'canonical nonnegative radial potential derivative')
    sphere_area = 8*s.pi**2/3
    zero(sphere_area*s.Rational(1, 4)*s.Rational(16, 35)*2
         -s.Rational(64, 105)*s.pi**2, 'full R5 normalization')
    f2 = -adv(f)+2*q*f
    angular = (12*g*s.diff(f, x)-16*gp*f)*(z*z-x/5)
    zero(f2-sphere_mean(f2)-angular, 'first nonlinear source loses radial symmetry')
    angular_poly = z*z-r*r/4
    zero(lap5(angular_poly), 'degree-two angular mode is harmonic in R5')
    zero(sphere_mean(q)+s.Rational(2, 5)*f,
         'the radial initial strain depletes every positive radial swirl moment')
    return {'radial_source': 'f(x)>=0, x=|y|^2; F=(-Delta5)^-1 f; g=-F_prime',
            'canonical_g': 'g(x)=1/(4 x^(5/2)) integral_0^x y^(3/2) f(y)dy >=0',
            'return': '-(64pi^2/105) integral_0^infinity x^(7/2)(g_prime)^2[13f+36g]dx',
            'sign': 'strictly negative for every nonzero smooth rapidly decaying radial f=b0^2',
            'critical_comparison': 'R_p(actual)-R_p(B,a_cal)=-(p-1)t^2/5 integral |b0|^(p+2)+o(t^2), p=5/2',
            'angular_defect': '(f2_nonlin)_nonradial=[12g f_prime-16g_prime f]*(z^2-x/5)',
            'angular_diffusion': 'this degree-two mode has spherical Laplacian eigenvalue -10',
            'warning': 'radial seed geometry is generally not invariant; no iteration of this comparison is justified'}


def explicit_family():
    c = s.symbols('c', real=True)
    base = 1+r*r+z*z
    F = base**(-s.Rational(3, 2))+c*z*z*base**(-s.Rational(7, 2))
    f = s.factor(-lap5(F))
    zero(f-((15-2*c)*base**2+63*c*z*z)/base**s.Rational(11, 2),
         'exact positive-source family')
    zero(base**2-4*z*z-(r*r+(z-1)**2)*(r*r+(z+1)**2),
         'z^2/base^2 is at most one quarter')
    chi = s.diff(F, z)
    zero(-lap5(chi)-s.diff(f, z), 'canonical generated parent matches the source')
    v, q = velocity(chi), 2*s.diff(chi, z)
    zero(s.diff(v[0], r)+v[0]/r+s.diff(v[1], z),
         'the generated physical meridional acceleration is divergence-free')
    zero(s.diff(v[0]-r*f, z)-s.diff(v[1], r),
         'its difference from the centrifugal acceleration is a pressure gradient')
    value = rational_integral(-f*(v.dot(grad(q))+q*q)/2)
    polynomial = 46844*c**3-22283310*c**2+54483750*c-69784875
    zero(value-32768*s.pi**2*polynomial/727840488375,
         'exact anisotropic return for every parameter')
    center, margin = s.Rational(1816125, 1462132), s.Rational(52560048619125, 1462132)
    zero(polynomial+21931980*(c-center)**2+margin
         -46844*c*c*(c-s.Rational(15, 2)), 'strict sign certificate on the source-positive interval')
    zero(value.subs(c, 0)+s.Rational(1015808, 323323)*s.pi**2,
         'radial rational fixture agrees with the universal identity')
    f0, v0, q0 = f.subs(c, 0), v.subs(c, 0), q.subs(c, 0)
    f2 = s.factor(-v0.dot(grad(f0))+2*q0*f0)
    zero(f2-45*(3*r*r+2*z*z-4)/base**7,
         'explicit actual second source jet generates a nonradial component')
    radial_g = s.Rational(3, 2)/(1+x)**s.Rational(5, 2)
    radial_f = 15/(1+x)**s.Rational(7, 2)
    check = x**s.Rational(7, 2)*s.diff(radial_g, x)**2*(13*radial_f+36*radial_g)
    # Two elementary beta integrals independently evaluate the radial formula.
    radial_value = -s.Rational(64, 105)*s.pi**2*s.Rational(675, 16)*(
        18*s.beta(s.Rational(11, 2), 5)+83*s.beta(s.Rational(9, 2), 6))
    zero(check-s.Rational(675, 16)*x**s.Rational(7, 2)*(18*x+83)/(1+x)**s.Rational(21, 2),
         'radial integrand for independent beta comparison')
    zero(s.expand_func(radial_value.rewrite(s.gamma))-value.subs(c, 0),
         'independent radial and angular integrations agree')
    require(margin > 0, 'strict polynomial margin')
    return {'potential': '(1+|y|^2)^(-3/2)+c z^2(1+|y|^2)^(-7/2)',
            'source_positive': '-12/11<c<15/2 gives f=-Delta5 F>0 and smooth b0=sqrt(f)',
            'return': str(value), 'radial_return': str(value.subs(c, 0)),
            'physical_scope': 'smooth finite-energy pure-swirl data with all physical L2 derivatives; algebraic tails, not Schwartz',
            'source_geometry': 'at c=0, f2_nonlin=45(3r^2+2z^2-4)/(1+r^2+z^2)^7',
            'not_claimed': 'invariance of this family, a global reference, a time-uniform gain, or critical-history closure'}


if __name__ == '__main__':
    print(json.dumps({'actual_jets': actual_jets(), 'radial_return': radial_identity(),
                      'explicit_family': explicit_family()}, indent=2))
